import com.example.ancapp.data.Visit
import com.example.ancapp.navigation.AncNavigation
import kotlinx.coroutines.launch
import java.time.LocalDate

class MainActivity : ComponentActivity() {
  override fun onCreate(savedInstanceState: Bundle?) {
    super.onCreate(savedInstanceState)

    val database = AncDatabase.getInstance(this)
    val repository = AncRepository(database.patientDao(), database.visitDao())

    lifecycleScope.launch {
      initializeDataIfNeeded(database)
    }

    setContent {
      MaterialTheme {
        Surface {
          AncNavigation(repository)
        }
      }
    }
  }

  private suspend fun initializeDataIfNeeded(database: AncDatabase) {
    val patientCount = database.patientDao().getAllPatients().collect { it.size }
    if (patientCount == 0) {
      val patients = listOf(
        Patient(
          name = "Emily Carter",
          dateOfBirth = LocalDate.of(1996, 4, 12),
          estimatedDueDate = LocalDate.of(2026, 12, 5)
        ),
        Patient(
          name = "Sarah Mitchell",
          dateOfBirth = LocalDate.of(1990, 11, 2),
          estimatedDueDate = LocalDate.of(2027, 1, 20)
        ),
        Patient(
          name = "Grace Thompson",
          dateOfBirth = LocalDate.of(2001, 7, 30),
          estimatedDueDate = LocalDate.of(2026, 10, 15)
        )
      )

      val patientIds = mutableListOf<Long>()
      for (patient in patients) {
        patientIds.add(database.patientDao().insertPatient(patient))
      }

      val visits = listOf(
        Visit(
          patientId = patientIds[0],
          visitDate = LocalDate.of(2026, 8, 10),
          gestationalAgeWeeks = 36,
          weightKg = 68.5,
          systolicBP = 118,
