          systolicBP = 110,
          diastolicBP = 70,
          hemoglobinGdL = 12.4,
          dangerSigns = "",
          notes = ""
        ),
        Visit(
          patientId = patientIds[2],
          visitDate = LocalDate.of(2026, 8, 5),
          gestationalAgeWeeks = 33,
          weightKg = 72.0,
          systolicBP = 128,
          diastolicBP = 84,
          hemoglobinGdL = 10.2,
