@Composable
fun VisitFormScreen(
    viewModel: VisitFormViewModel,
    onBackClick: () -> Unit,
    onSaveSuccess: () -> Unit
) {
    var visitDate by remember { mutableStateOf(LocalDate.now().toString()) }
    var gestationalAgeWeeks by remember { mutableStateOf("") }
    var weightKg by remember { mutableStateOf("") }
    var systolicBP by remember { mutableStateOf("") }
    var diastolicBP by remember { mutableStateOf("") }
    var hemoglobinGdL by remember { mutableStateOf("") }
    var notes by remember { mutableStateOf("") }

    var vaginalBleeding by remember { mutableStateOf(false) }
    var severeHeadache by remember { mutableStateOf(false) }
    var blurredVision by remember { mutableStateOf(false) }
    var fever by remember { mutableStateOf(false) }

    val coroutineScope = rememberCoroutineScope()

    Scaffold(
        topBar = {
            TopAppBar(
                title = { Text("Record ANC Visit") },
                navigationIcon = {
                    IconButton(onClick = onBackClick) {
                        Icon(Icons.AutoMirrored.Filled.ArrowBack, contentDescription = "Back")
                    }
                }
            )
        }
    ) { innerPadding ->
        LazyColumn(
            modifier = Modifier
                .padding(innerPadding)
                .padding(16.dp)
                .fillMaxWidth()
        ) {
            item {
                OutlinedTextField(
                    value = visitDate,
                    onValueChange = { visitDate = it },
                    label = { Text("Visit Date (YYYY-MM-DD)") },
                    modifier = Modifier.fillMaxWidth()
                )
            }

            item {
                OutlinedTextField(
                    value = gestationalAgeWeeks,
                    onValueChange = { gestationalAgeWeeks = it },
                    label = { Text("Gestational Age (weeks)") },
                    keyboardOptions = KeyboardOptions(keyboardType = KeyboardType.Number),
                    modifier = Modifier.fillMaxWidth().padding(top = 8.dp)
                )
            }

            item {
                OutlinedTextField(
                    value = weightKg,
                    onValueChange = { weightKg = it },
                    label = { Text("Weight (kg)") },
                    keyboardOptions = KeyboardOptions(keyboardType = KeyboardType.Decimal),
                    modifier = Modifier.fillMaxWidth().padding(top = 8.dp)
                )
            }

            item {
                Row(modifier = Modifier.fillMaxWidth().padding(top = 8.dp)) {
                    OutlinedTextField(
                        value = systolicBP,
                        onValueChange = { systolicBP = it },
                        label = { Text("Systolic") },
                        keyboardOptions = KeyboardOptions(keyboardType = KeyboardType.Number),
                        modifier = Modifier.weight(1f).padding(end = 4.dp)
                    )
                    OutlinedTextField(
                        value = diastolicBP,
                        onValueChange = { diastolicBP = it },
                        label = { Text("Diastolic") },
                        keyboardOptions = KeyboardOptions(keyboardType = KeyboardType.Number),
                        modifier = Modifier.weight(1f).padding(start = 4.dp)
                    )
                }
            }

            item {
                OutlinedTextField(
                    value = hemoglobinGdL,
                    onValueChange = { hemoglobinGdL = it },
                    label = { Text("Hemoglobin (g/dL) - optional") },
                    keyboardOptions = KeyboardOptions(keyboardType = KeyboardType.Decimal),
                    modifier = Modifier.fillMaxWidth().padding(top = 8.dp)
                )
            }

            item {
                Text(
                    text = "Danger Signs",
                    style = MaterialTheme.typography.bodyLarge,
                    modifier = Modifier.padding(top = 16.dp)
                )
            }

            item {
                DangerSignCheckbox("Vaginal bleeding", vaginalBleeding) {
                    vaginalBleeding = it
                }
            }

            item {
                DangerSignCheckbox("Severe headache", severeHeadache) {
                    severeHeadache = it
                }
            }

            item {
                DangerSignCheckbox("Blurred vision", blurredVision) {
                    blurredVision = it
                }
            }

            item {
                DangerSignCheckbox("Fever", fever) {
                    fever = it
                }
            }

            item {
                OutlinedTextField(
                    value = notes,
                    onValueChange = { notes = it },
                    label = { Text("Notes") },
                    modifier = Modifier.fillMaxWidth().padding(top = 8.dp),
                    minLines = 3
                )
            }

            item {
                Button(
                    onClick = {
                        coroutineScope.launch {
                            val dangerSigns = mutableListOf<String>().apply {
                                if (vaginalBleeding) add("vaginal bleeding")
                                if (severeHeadache) add("severe headache")
                                if (blurredVision) add("blurred vision")
                                if (fever) add("fever")
                            }.joinToString(", ")

                            try {
                                val date = LocalDate.parse(visitDate)
                                viewModel.saveVisit(
                                    visitDate = date,
                                    gestationalAgeWeeks = gestationalAgeWeeks.toIntOrNull() ?: 0,
                                    weightKg = weightKg.toDoubleOrNull() ?: 0.0,
                                    systolicBP = systolicBP.toIntOrNull() ?: 0,
                                    diastolicBP = diastolicBP.toIntOrNull() ?: 0,
                                    hemoglobinGdL = hemoglobinGdL.toDoubleOrNull(),
                                    dangerSigns = dangerSigns,
                                    notes = notes
                                )
                                onSaveSuccess()
                            } catch (e: Exception) {
                                e.printStackTrace()
                            }
                        }
                    },
                    modifier = Modifier.fillMaxWidth().padding(top = 16.dp)
                ) {
                    Text("Save Visit")
                }
            }
        }
    }
}

